mapper.select:
SELECT ei.elderly_id AS elderlyId, ei.name AS name, ei.check_in_time AS checkInDate, ei.bed_id AS bedId, ei.check_out_time AS checkOutDate, ci.checkout_type AS checkoutType, ci.approval_status AS approvalStatus, ci.approval_person AS approvalPerson, ci.approval_time AS approvalTime FROM elderly_info ei LEFT JOIN check_out_requests ci ON ei.elderly_id = ci.elderly_id WHERE 1 = 1
AND ei.name LIKE CONCAT('%', #{name}, '%')
AND ei.bed_id = #{bedId}
AND ei.check_in_time = #{checkInDate}
